+/// Gets whether the pattern is a non-negated glob pattern
+/// as opposed to a literal path.
+fn is_positive_glob_pattern(pattern: &GlobPattern) -> bool {
+  !pattern.is_negated() && is_pattern(&pattern.relative_pattern)
+}
